def upgrade():
    connection = op.get_bind()
    reserved = {name.casefold() for name in OBJECTS}
    # Preflight the complete local namespace before any mutation. Unrelated
    # local tables, columns, indexes, triggers and views are preserved verbatim.
    for _, name, _ in connection.exec_driver_sql('PRAGMA database_list'):
        quoted = '"' + name.replace('"', '""') + '"'
        existing = connection.exec_driver_sql('SELECT name FROM '+quoted+'.sqlite_schema').fetchall()
        if any(row[0].casefold() in reserved for row in existing):
            raise RuntimeError('Reconciliation storage name collision')
    for statement in (*DDL, *GUARDS):
        connection.exec_driver_sql(statement)
    # N never backfills or activates. Check explicit emptiness even with FK OFF.
    for name in NEW_TABLES:
        if connection.exec_driver_sql('SELECT 1 FROM main."'+name+'" LIMIT 1').fetchone():
            raise RuntimeError('Reconciliation storage must be empty')


